#!/usr/bin/env -S uv run --quiet --script
# managed by devkit — do not edit; fix upstream in ~/Developer/projects/devkit
# /// script
# requires-python = ">=3.10"
# dependencies = ["pyyaml"]
# ///
"""Docs tooling: legacy ADRs, work folders, cross-refs, the decisions.md render.

    uv run --quiet --script scripts/kit/docs.py {feature new|feature archive|index|check|tracker next|resume}
    uv run --quiet --script scripts/kit/docs.py {adr new|backlog new}      refused: they name the `devkit rec` verb that writes now

Python 3.10, stdlib + PyYAML (the PEP 723 header above; run it under uv, never a bare python3, FB-393). Repo root = two levels above this file (override: env DOCS_ROOT).
docs.py never calls devkit and reads no store index: the rulings and backlog stores are written, indexed and linted
by `devkit rec`, which the make fragment (mk/kit-docs.mk) runs next to this tool once a store index exists.
Here: the ADR lint and the decisions.md render (only while docs/decisions/ holds ADR files), the work-folder trackers
and size caps, and the cross-reference lint, which resolves ids by file existence.
The backlog id prefix comes from KIT_ID_PREFIX (env, else KIT_ID_PREFIX in .devkit/config.env).
KIT_DOCS_TRACKERS=off (environment only, never config.env; a project exports it in its own Makefile) skips the
tracker lint whole, the missing-tracker.yaml check included, for a repo whose tracker lives elsewhere. ADR,
cross-reference and generated-index lints and the work-folder size caps still run. Any other value, an empty one
too, is refused.
"""
from __future__ import annotations

import argparse
import configparser
import datetime
import fnmatch
import os
import posixpath
import re
import shutil
import subprocess
import sys
from collections import Counter, namedtuple
from pathlib import Path

import yaml

LOADER = getattr(yaml, "CSafeLoader", yaml.SafeLoader)
GEN = "GENERATED by scripts/kit/docs.py index — do not edit"
ADR_STATUS = ("proposed", "accepted", "superseded", "deferred")
EPIC_STATUS = ("discovery", "ready", "in-progress", "paused", "done")
PHASE_STATUS = ("planned", "spec-ready", "in-progress", "review", "done", "deferred", "re-scoped")
SKIPPED = ("done", "deferred", "re-scoped")  # phases never offered by `tracker next`
CAPS = (("README.md", 100), ("rulings.md", 80), ("plans/handoff.md", 60))
SPEC_CAP = 150
Doc = namedtuple("Doc", "path meta body err")


# ---------------------------------------------------------------- basics
def root() -> Path:
    env = os.environ.get("DOCS_ROOT")
    return Path(env).resolve() if env else Path(__file__).resolve().parents[2]


def id_prefix() -> str:
    """Backlog id prefix: env KIT_ID_PREFIX, else the KIT_ID_PREFIX line of .devkit/config.env."""
    val = os.environ.get("KIT_ID_PREFIX", "").strip()
    cfg = root() / ".devkit/config.env"
    if not val and cfg.is_file():
        for line in cfg.read_text(encoding="utf-8").splitlines():
            m = re.match(r"\s*KIT_ID_PREFIX\s*=\s*[\"']?([A-Za-z0-9]+)[\"']?\s*(?:#.*)?$", line)
            if m:
                val = m.group(1)
    if not re.fullmatch(r"[A-Z][A-Z0-9]*", val):
        sys.exit("docs: KIT_ID_PREFIX (uppercase letters/digits) is not set in the environment or .devkit/config.env")
    return val


def rel(path: Path) -> str:
    try:
        return str(path.relative_to(root()))
    except ValueError:
        return str(path)


def err(path: Path, msg: str) -> str:
    return f"{rel(path)}: {msg}"


def as_date(v) -> str | None:
    if isinstance(v, datetime.date):
        return v.isoformat()
    if isinstance(v, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", v):
        try:
            datetime.date.fromisoformat(v)
            return v
        except ValueError:
            return None
    return None


def as_list(v) -> list:
    return [] if v is None else v if isinstance(v, list) else [v]


def is_int(v) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def nonempty_str(v) -> bool:
    return isinstance(v, str) and bool(v.strip())


def read_front(path: Path) -> Doc:
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        return Doc(path, None, "", f"unreadable ({e})")
    m = re.match(r"---[ \t]*\n(.*?)\n---[ \t]*(?:\n|$)(.*)", text, re.S)
    if not m:
        return Doc(path, None, text, "missing front matter")
    try:
        meta = yaml.load(m.group(1), Loader=LOADER)
    except yaml.YAMLError:
        return Doc(path, None, m.group(2), "invalid YAML front matter")
    if not isinstance(meta, dict):
        return Doc(path, None, m.group(2), "front matter is not a mapping")
    return Doc(path, meta, m.group(2), None)


def load_docs(subdir: str, prefix: str) -> list[Doc]:
    return [read_front(p) for p in sorted((root() / subdir).glob(f"{prefix}*.md"))]


def load_yaml(path: Path):
    try:
        return yaml.load(path.read_text(encoding="utf-8"), Loader=LOADER), None
    except (OSError, UnicodeDecodeError, yaml.YAMLError) as e:
        return None, f"unreadable YAML ({type(e).__name__})"


def active_epics() -> list[tuple[str, Path]]:
    base = root() / "docs/features/active"
    return sorted((p.name, p) for p in base.glob("*") if p.is_dir() and not p.name.startswith("."))


def archived_epics() -> list[tuple[str, Path]]:
    base = root() / "docs/features/archive"
    return sorted((p.name, p) for p in base.glob("*/*") if p.is_dir())


def epic_slugs() -> set[str]:
    return {s for s, _ in active_epics() + archived_epics()}


# ---------------------------------------------------------------- ADR lint
def lint_adr_fields(d: Doc) -> list[str]:
    if d.err:
        return [err(d.path, d.err)]
    m, out = d.meta, []
    fm = re.fullmatch(r"(ADR-\d{3})-[a-z0-9]+(?:-[a-z0-9]+)*\.md", d.path.name)
    if not fm:
        out.append(err(d.path, "file name must be ADR-NNN-kebab-slug.md"))
    elif m.get("id") != fm.group(1):
        out.append(err(d.path, f"id {m.get('id')!r} does not match file name"))
    if not nonempty_str(m.get("title")):
        out.append(err(d.path, "title missing"))
    if m.get("status") not in ADR_STATUS:
        out.append(err(d.path, f"status {m.get('status')!r} not in {list(ADR_STATUS)}"))
    scope = m.get("scope")
    if scope != "project":
        slug = scope[5:] if isinstance(scope, str) and scope.startswith("epic:") else None
        if slug is None:
            out.append(err(d.path, f"scope {scope!r} must be 'project' or 'epic:<slug>'"))
        elif slug not in epic_slugs():
            out.append(err(d.path, f"scope epic '{slug}' does not exist"))
    if as_date(m.get("date")) is None:
        out.append(err(d.path, "date must be YYYY-MM-DD"))
    for h in ("Context", "Decision", "Consequences"):
        if not re.search(rf"^## {h}\s*$", d.body, re.M):
            out.append(err(d.path, f"missing '## {h}' heading"))
    return out


def lint_adr_unique(docs: list[Doc]) -> list[str]:
    seen: dict[str, Path] = {}
    out = []
    for d in docs:
        i = d.meta.get("id") if d.meta else None
        if isinstance(i, str) and i in seen:
            out.append(err(d.path, f"duplicate id {i} (also {rel(seen[i])})"))
        elif isinstance(i, str):
            seen[i] = d.path
    return out


def lint_adr_links(docs: list[Doc]) -> list[str]:
    by = {d.meta["id"]: d for d in docs if d.meta and isinstance(d.meta.get("id"), str)}
    out = []
    for me, d in sorted(by.items()):
        m = d.meta
        for tgt in as_list(m.get("supersedes")):
            if tgt not in by:
                out.append(err(d.path, f"supersedes unknown {tgt}"))
                continue
            if by[tgt].meta.get("superseded_by") != me:
                out.append(err(d.path, f"supersedes {tgt} but {tgt}.superseded_by != {me}"))
            if by[tgt].meta.get("status") != "superseded":
                out.append(err(by[tgt].path, f"superseded by {me} but status is not 'superseded'"))
        sb = m.get("superseded_by")
        if sb is not None:
            if sb not in by:
                out.append(err(d.path, f"superseded_by unknown {sb}"))
            elif me not in as_list(by[sb].meta.get("supersedes")):
                out.append(err(d.path, f"superseded_by {sb} but {sb}.supersedes lacks {me}"))
        for tgt in as_list(m.get("amends")):
            if tgt not in by:
                out.append(err(d.path, f"amends unknown {tgt}"))
            elif me not in as_list(by[tgt].meta.get("amended_by")):
                out.append(err(d.path, f"amends {tgt} but {tgt}.amended_by lacks {me}"))
        for src in as_list(m.get("amended_by")):
            if src not in by:
                out.append(err(d.path, f"amended_by unknown {src}"))
            elif me not in as_list(by[src].meta.get("amends")):
                out.append(err(d.path, f"amended_by {src} but {src}.amends lacks {me}"))
    return out


def lint_adrs() -> list[str]:
    docs = load_docs("docs/decisions", "ADR-")
    out = [e for d in docs for e in lint_adr_fields(d)]
    return out + lint_adr_unique(docs) + lint_adr_links([d for d in docs if d.meta])


# ---------------------------------------------------------------- tracker lint
def phase_list(t: dict) -> list[dict]:
    return [p for p in as_list(t.get("phases")) if isinstance(p, dict) and nonempty_str(p.get("id"))]


def lint_tracker_header(t: dict, slug: str) -> list[str]:
    out = []
    if t.get("epic") != slug:
        out.append(f"epic {t.get('epic')!r} != directory name '{slug}'")
    if not nonempty_str(t.get("title")):
        out.append("title missing")
    if t.get("status") not in EPIC_STATUS:
        out.append(f"status {t.get('status')!r} not in {list(EPIC_STATUS)}")
    if not nonempty_str(t.get("owner")):
        out.append("owner missing")
    if as_date(t.get("started")) is None:
        out.append("started must be YYYY-MM-DD")
    if not nonempty_str(t.get("goal")) or len(t["goal"]) > 300:
        out.append("goal missing or longer than 300 chars")
    r = t.get("resume")
    if not isinstance(r, dict):
        return out + ["resume missing"]
    # `next` and `current_wave` are optional (nothing reads them); a tracker that has them is checked as before
    if "next" in r and (not nonempty_str(r["next"]) or len(r["next"]) > 400):
        out.append("resume.next empty or longer than 400 chars (narrative belongs in handoff.md)")
    if "current_wave" in r and (not is_int(r["current_wave"]) or r["current_wave"] < 0):
        out.append("resume.current_wave must be an int >= 0")
    if not nonempty_str(r.get("handoff")):
        out.append("resume.handoff must be a path or 'none'")
    return out


def lint_tracker_phases(t: dict) -> list[str]:
    """Per-phase schema: required keys, vocab, id uniqueness."""
    out, seen = [], set()
    raw = t.get("phases")
    if not isinstance(raw, list):
        return ["phases must be a list (empty while the work folder is a stub)"]
    for p in raw:
        pid = p.get("id") if isinstance(p, dict) else None
        if not isinstance(pid, str) or not re.fullmatch(r"[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*", pid):
            out.append(f"phase id {pid!r} must be UPPER-KEBAB (e.g. P-AUTH)")
            continue
        if pid in seen:
            out.append(f"duplicate phase id {pid}")
        seen.add(pid)
        status = p.get("status")
        if not nonempty_str(p.get("title")):
            out.append(f"{pid}: title missing")
        if status not in PHASE_STATUS:
            out.append(f"{pid}: status {status!r} not in {list(PHASE_STATUS)}")
        if not is_int(p.get("wave")) or p["wave"] < 1:
            out.append(f"{pid}: wave must be an int >= 1")
        if not isinstance(p.get("depends_on"), list):
            out.append(f"{pid}: depends_on must be a list (may be empty)")
        area = p.get("area")
        if status not in ("deferred", "re-scoped") and not (
                isinstance(area, list) and area and all(nonempty_str(a) for a in area)):
            out.append(f"{pid}: area must be a non-empty list of globs")
        if not nonempty_str(p.get("spec")):
            out.append(f"{pid}: spec missing")
        if "note" in p and (not isinstance(p["note"], str) or len(p["note"]) > 200):
            out.append(f"{pid}: note longer than 200 chars")
    return out


CROSS_REF_RE = re.compile(r"([a-z][a-z0-9]*(?:-[a-z0-9]+)*):([A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*)")


def cross_dep_problem(dep: str, slug: str) -> str | None:
    """FB-571: why `dep` (an `<epic>:<PHASE>` entry of a phase of `slug`) is not valid, else None. A small copy of
    cross_dep_problem in devkit's lib/devkit/core/tracker.py (this script cannot import devkit): the other epic's tracker
    sits under docs/features/active, else archive/*/, and carries that phase. No wave order, no cycle across epics."""
    m = CROSS_REF_RE.fullmatch(dep)
    if not m:
        return "must be <epic>:<PHASE> (e.g. other-epic:P-AUTH)"
    epic, phase = m.groups()
    if epic == slug:
        return f"that is this epic; name the phase as {phase}"
    base = root() / "docs/features"
    path = base / "active" / epic / "tracker.yaml"
    if not path.is_file():
        path = next(iter(sorted((base / "archive").glob(f"*/{epic}/tracker.yaml"))), None)
    if path is None:
        return f"no epic {epic} under docs/features/active or archive"
    other, e = load_yaml(path)
    if e:
        return f"the tracker of {epic} is unreadable"
    if phase not in {p.get("id") for p in phase_list(other if isinstance(other, dict) else {})}:
        return f"epic {epic} has no phase {phase}"
    return None


def lint_tracker_deps(t: dict, slug: str) -> list[str]:
    ph = {p["id"]: p for p in phase_list(t)}
    out = []
    for pid, p in sorted(ph.items()):
        for dep in as_list(p.get("depends_on")):
            if isinstance(dep, str) and ":" in dep:  # FB-571: another epic's phase, as `devkit phase amend --after` writes
                if why := cross_dep_problem(dep, slug):
                    out.append(f"{pid}: depends_on {dep}: {why}")
            elif dep not in ph:
                out.append(f"{pid}: depends_on unknown phase {dep}")
            elif is_int(p.get("wave")) and is_int(ph[dep].get("wave")) and p["wave"] <= ph[dep]["wave"]:
                out.append(f"{pid}: wave {p['wave']} must be > wave {ph[dep]['wave']} of dependency {dep}")
    return out + lint_tracker_cycles(ph)


def lint_tracker_cycles(ph: dict) -> list[str]:
    state: dict[str, int] = {}  # 1 = on stack, 2 = done
    out: list[str] = []

    def visit(pid: str, stack: list[str]) -> None:
        state[pid] = 1
        for dep in as_list(ph[pid].get("depends_on")):
            if dep not in ph:
                continue
            if state.get(dep) == 1:
                out.append("dependency cycle: " + " -> ".join(stack[stack.index(dep):] + [dep]))
            elif dep not in state:
                visit(dep, stack + [dep])
        state[pid] = 2

    for pid in sorted(ph):
        if pid not in state:
            visit(pid, [pid])
    return out


def segments_meet(x: str, y: str) -> bool:
    """Can two path segments match one name? Literals must be equal, a literal must match the other's pattern, and two
    patterns are taken to meet unless their literal prefixes or suffixes conflict (FB-528)."""
    wild = [any(c in s for c in "*?[") for s in (x, y)]
    if not any(wild):
        return x == y
    if all(wild):
        pre = [re.split(r"[*?\[]", s, maxsplit=1)[0] for s in (x, y)]  # the literal up to the first wildcard
        suf = [re.split(r"[*?\[\]]", s)[-1] for s in (x, y)]  # the literal after the last wildcard or bracket
        return (pre[0].startswith(pre[1]) or pre[1].startswith(pre[0])) and (
            suf[0].endswith(suf[1]) or suf[1].endswith(suf[0]))
    lit, pat = (y, x) if wild[0] else (x, y)
    return fnmatch.fnmatchcase(lit, pat)


def glob_segments(g: str) -> list[str]:
    """The path segments of a glob; a trailing or doubled `/` adds none (`src/` is `src`)."""
    return [s for s in g.split("/") if s]


def glob_overlap(ga: str, gb: str) -> bool:
    """Two globs overlap when every segment pair, from the left, can match one name; a `**` segment takes the rest, and a
    shorter glob names a folder holding the other."""
    for sa, sb in zip(glob_segments(ga), glob_segments(gb)):
        if sa == "**" or sb == "**":
            return True
        if not segments_meet(sa, sb):
            return False
    return True


def generated_paths() -> set[str]:
    """The exact paths the `[compose]` `generated` rows of config/modules.ini list (FB-798): no overlap verdict sees them.
    Standalone, as this script is: only the `generated` key's `<path> <make target>` rows are read, so an absent or
    unreadable file exempts nothing (`scripts/kit/modules.py lint` is the one that judges the file)."""
    ini = root() / "config" / "modules.ini"
    if not ini.is_file():
        return set()
    cp = configparser.ConfigParser(interpolation=None, inline_comment_prefixes=(";",), default_section="\0no-default-section")
    cp.optionxform = str  # type: ignore[assignment]
    try:
        cp.read_string(ini.read_text(encoding="utf-8"))
    except (configparser.Error, OSError, UnicodeDecodeError):
        return set()
    rows = cp.get("compose", "generated", fallback="")
    return {posixpath.normpath(w[0]) for w in (line.split() for line in rows.splitlines()) if w}


def generated_pair(ga: str, gb: str, generated: set[str]) -> bool:
    """Is an overlapping pair a generated file? Only an exact path (no glob character) on either side is judged."""
    return any(not re.search(r"[*?\[{]", g) and posixpath.normpath(g) in generated for g in (ga, gb))


def lint_tracker_areas(t: dict) -> list[str]:
    generated = generated_paths()
    by_wave: dict[int, list[dict]] = {}
    for p in phase_list(t):
        if p.get("status") not in SKIPPED and is_int(p.get("wave")):  # finished phases hold no area
            by_wave.setdefault(p["wave"], []).append(p)
    out = []
    for wave, group in sorted(by_wave.items()):
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                for ga in (g for g in as_list(a.get("area")) if isinstance(g, str)):
                    for gb in (g for g in as_list(b.get("area")) if isinstance(g, str)):
                        if glob_overlap(ga, gb) and not generated_pair(ga, gb, generated):
                            out.append(f"wave {wave}: {a['id']} area '{ga}' overlaps {b['id']} area '{gb}'")
    return out


def lint_tracker_specs(t: dict, edir: Path) -> list[str]:
    out, refs = [], Counter()
    for p in phase_list(t):
        spec = p.get("spec")
        if not nonempty_str(spec):
            continue
        refs[os.path.normpath(spec)] += 1
        if p.get("status") != "planned" and not (edir / spec).is_file():
            out.append(f"{p['id']}: spec '{spec}' does not exist")
    for f in sorted((edir / "specs").glob("*.md")):
        n = refs.get(os.path.normpath(f"specs/{f.name}"), 0)
        if n != 1:
            out.append(f"specs/{f.name} is referenced by {n} phases (must be exactly 1)")
    return out


def lint_tracker_handoff(t: dict, edir: Path) -> list[str]:
    r = t.get("resume")
    h = r.get("handoff") if isinstance(r, dict) else None
    if nonempty_str(h) and h != "none" and not (edir / h).is_file():
        return [f"resume.handoff '{h}' does not exist"]
    return []


def lint_caps(edir: Path) -> list[str]:
    files = [(edir / name, cap) for name, cap in CAPS]
    files += [(f, SPEC_CAP) for f in sorted((edir / "specs").glob("*.md"))]
    out = []
    for f, cap in files:
        if f.is_file():
            n = len(f.read_text(encoding="utf-8", errors="replace").splitlines())
            if n > cap:
                out.append(err(f, f"{n} lines > {cap}"))
    return out


def lint_trackers() -> list[str]:
    out = []
    for slug, edir in active_epics() + archived_epics():
        tp = edir / "tracker.yaml"
        if not tp.is_file():
            if edir.parent.name == "active":
                out.append(err(tp, "missing"))
        else:
            t, e = load_yaml(tp)
            if e or not isinstance(t, dict):
                out.append(err(tp, e or "tracker is not a mapping"))
            else:
                reasons = (lint_tracker_header(t, slug) + lint_tracker_phases(t) + lint_tracker_deps(t, slug)
                           + lint_tracker_areas(t) + lint_tracker_specs(t, edir)
                           + lint_tracker_handoff(t, edir))
                out += [err(tp, r) for r in reasons]
    return out


def trackers_off() -> bool:
    """KIT_DOCS_TRACKERS from the environment only: unset -> lint, 'off' -> skip lint_trackers, anything else refuses."""
    v = os.environ.get("KIT_DOCS_TRACKERS")
    if v is None:
        return False
    if v == "off":
        return True
    sys.exit(f"docs: KIT_DOCS_TRACKERS={v!r} is not valid — it is 'off' or unset")


# ---------------------------------------------------------------- cross-ref
def strip_fences(text: str) -> str:
    out, fence = [], None
    for line in text.splitlines():
        m = re.match(r"\s*(`{3,}|~{3,})", line)
        if fence is None and m:
            fence = m.group(1)
        elif fence and m and m.group(1)[0] == fence[0] and len(m.group(1)) >= len(fence):
            fence = None
        elif fence is None:
            out.append(line)
            continue
        out.append("")  # keep line numbers stable
    return "\n".join(out)


def stored_ids(base: Path, stem: str, slug: bool) -> set[str]:
    """Ids of the files `<base>/<stem>N[-slug].md` and `<base>/archive/*/…` (by file name; no index is read)."""
    found = set()
    tail = r"-[a-z0-9].*\.md" if slug else r"\.md"
    for p in list(base.glob(f"{stem}*.md")) + list(base.glob(f"archive/*/{stem}*.md")):
        if m := re.fullmatch(rf"({stem}\d+){tail}", p.name):
            found.add(m.group(1))
    return found


def r_key(ref: str) -> str:
    """`R-001` and `R-1` are the same ruling (standards/docs.md): R ids compare by number; other prefixes are as written."""
    m = re.fullmatch(r"R-(\d+)", ref)
    return f"R-{int(m.group(1))}" if m else ref


# FB-611: `<repo>:R-n` (also `<repo>:ADR-n`, `<repo>:<PREFIX>-n`) cites another repo's record; it is never looked up here.
# `repo` is lower-kebab and stands alone: a word, `/`, `.`, `:`, `@`, `%`, `#`, `~` or `-` before it (`http://x:R-1`,
# `docs/foo:R-1`, `a.com:R-1`, `me@host:R-1`) means it is a URL or path piece, not a qualifier, and the cite stays checked.
# `backlog.cite_checker` carries the same pattern (FB-543).
QUALIFIED = re.compile(r"(?<![\w/.:@%#~-])[a-z][a-z0-9]*(?:-[a-z0-9]+)*:[A-Z][A-Z0-9]*-\d+\b")


def unqualified(line: str) -> str:
    """The line with every repo-qualified cite blanked (same length), so the cite pattern cannot see it."""
    return QUALIFIED.sub(lambda m: " " * len(m.group(0)), line)


def lint_cross_ref() -> list[str]:
    r = root()
    adrs = {m.group(1) for p in (r / "docs/decisions").glob("ADR-*.md")
            if (m := re.match(r"(ADR-\d{3})", p.name))}
    pre = id_prefix()
    items = stored_ids(r / "docs/backlog", f"{pre}-", slug=True)
    rulings = r / "docs/rulings.md"
    legacy = set(re.findall(r"^\|\s*(R-\d{3})\s*\|", rulings.read_text(encoding="utf-8"), re.M)) \
        if rulings.is_file() else set()
    store = (r / "docs/rulings").is_dir()  # the R-n store: ids are its files; its presence widens the pattern
    rs = legacy | (stored_ids(r / "docs/rulings", "R-", slug=False) if store else set())
    known = {"ADR": adrs, "R": {r_key(i) for i in rs}}  # R-n of any width is one ruling: R-001 is R-1.md
    known[pre] = known.get(pre, set()) | items
    rn = r"\d+" if store else r"\d{3}"  # a two-digit R-89 in prose is a host ruling unless the project keeps R-n files
    cite = rf"\b(?:(?:ADR|{pre})-\d{{3}}|R-{rn})\b"
    files = sorted(set((r / "docs").rglob("*.md")) | set((r / ".claude").rglob("*.md")))
    out = []
    for f in files:
        rel = f.relative_to(r).parts
        # research/ notes copy other repos' docs: not scanned, at docs/ or in a work folder (FB-339);
        # .claude/worktrees/ holds whole checkouts of agents, each with its own docs (FB-812, FB-813)
        if rel[:2] == ("docs", "research") or (rel[:2] == ("docs", "features") and "research" in rel[2:-1]) \
                or rel[:2] == (".claude", "worktrees") or not f.is_file():
            continue
        bad = set()
        for n, line in enumerate(strip_fences(f.read_text(encoding="utf-8", errors="replace")).splitlines(), 1):
            for m in re.finditer(cite, unqualified(line)):
                if r_key(m.group(0)) not in known[m.group(0).split("-")[0]] and m.group(0) not in bad:
                    bad.add(m.group(0))
                    out.append(err(f, f"line {n}: unknown reference {m.group(0)}"))
    return out


# ---------------------------------------------------------------- generated indexes
def md_cell(s) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def render_decisions() -> str:
    groups: dict[str, list[Doc]] = {"project": []}
    for d in load_docs("docs/decisions", "ADR-"):
        if d.meta:
            groups.setdefault(str(d.meta.get("scope", "project")), []).append(d)
    lines = ["# Decisions", "", GEN, "",
             "Status vocabulary: " + " · ".join(ADR_STATUS) + ".", ""]
    for scope in ["project"] + sorted(s for s in groups if s != "project"):
        lines += ["## project" if scope == "project" else f"## {scope.replace('epic:', 'epic: ', 1)}", ""]
        if not groups[scope]:
            lines += ["_No ADRs yet._", ""]
            continue
        lines += ["| ADR | Title | Status | Date |", "|---|---|---|---|"]
        for d in sorted(groups[scope], key=lambda d: d.path.name):
            m = d.meta
            lines.append(f"| [{md_cell(m.get('id', d.path.stem))}](decisions/{d.path.name}) "
                         f"| {md_cell(m.get('title', ''))} | {md_cell(m.get('status', ''))} "
                         f"| {md_cell(as_date(m.get('date')) or '')} |")
        lines.append("")
    return "\n".join(lines)


def has_adr_files() -> bool:
    return any((root() / "docs/decisions").glob("ADR-*.md"))


def generated() -> dict[str, str]:
    """Only the legacy decisions.md, and only while docs/decisions/ holds ADR files; the stores' indexes are rec's."""
    return {"docs/decisions.md": render_decisions()} if has_adr_files() else {}


def lint_generated() -> list[str]:
    out = []
    for name, want in generated().items():
        p = root() / name
        if not p.is_file() or p.read_text(encoding="utf-8") != want:
            out.append(err(p, "generated file is missing or stale — run `make docs`"))
    return out


# ---------------------------------------------------------------- commands
def cmd_index() -> int:
    changed = []
    for name, text in generated().items():
        p = root() / name
        if not p.is_file() or p.read_text(encoding="utf-8") != text:
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text, encoding="utf-8")
            changed.append(name)
    print("docs: regenerated " + ", ".join(changed) if changed else "docs: indexes up to date")
    return 0


def cmd_check(quiet: bool) -> int:
    skip_trackers = trackers_off()
    caps = [e for _, edir in active_epics() + archived_epics() for e in lint_caps(edir)]
    problems = (lint_adrs() + ([] if skip_trackers else lint_trackers()) + caps
                + lint_cross_ref() + lint_generated())
    for line in sorted(set(problems)):
        print(line)
    if problems:
        return 1
    if not quiet:
        print("docs-check: OK")
    return 0


def refuse(why: str, verb: str) -> int:
    """`adr new` and `backlog new` write nothing here any more: the store verbs of `devkit rec` do."""
    print(f"docs: {why} · next: {verb}", file=sys.stderr)
    return 2


STUB_MARK = "STUB:"
BINDING_RECORD = "plans/backlog-binding.md"  # the architect's record of backlog items bound to the epic (`devkit epic ready`)
SLUG_RE = re.compile(r"[a-z][a-z0-9]*(?:-[a-z0-9]+)*")
CLOSED_PHASES = ("done", "deferred", "re-scoped")


def git_user() -> str:
    try:
        name = subprocess.run(["git", "-C", str(root()), "config", "user.name"], capture_output=True, text=True).stdout
    except OSError:
        name = ""
    return " ".join(name.split()) or "unassigned"


def cmd_feature_new(slug: str) -> int:
    if not SLUG_RE.fullmatch(slug):
        sys.exit(f"feature new: slug {slug!r} must be kebab-case (lowercase letters, digits, dashes; start with a letter)")
    if slug in epic_slugs():
        sys.exit(f"feature new: '{slug}' already exists under docs/features/active or docs/features/archive")
    base = root() / "docs/features/active" / slug
    today = datetime.date.today().isoformat()
    readme = (f"<!-- {STUB_MARK} fill in goal, scope, non-scope and phase map, then delete this line (archive refuses while it stays) -->\n"
              f"# {slug}\n\n## Goal\n\nOne paragraph: the outcome, and how anyone can tell it is reached.\n\n"
              "## Scope\n\n- \n\n## Non-scope\n\n- \n\n## Phase map\n\nPhases live in `tracker.yaml`; one line each here.\n")
    tracker = {"epic": slug, "title": slug, "status": "discovery", "owner": git_user(), "started": today,
               "goal": f"TODO: one sentence — the outcome of {slug}", "phases": [],
               "resume": {"handoff": "plans/handoff.md"}}
    files = {
        "README.md": readme,
        "tracker.yaml": yaml.safe_dump(tracker, sort_keys=False, allow_unicode=True, width=1000),
        "rulings.md": f"# Rulings — {slug}\n\nOne line each, newest last: `D-n` owner rulings, `LR-n` lead rulings.\n",
        "specs/.gitkeep": "",
        "plans/handoff.md": f"# Handoff — {slug}\n\nRewritten at every wave boundary; the first file read after a compact or a new session.\n",
    }
    for name, text in files.items():
        path = base / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        print(rel(path))
    return 0


def cmd_feature_archive(slug: str) -> int:
    src = root() / "docs/features/active" / slug
    if not SLUG_RE.fullmatch(slug) or not src.is_dir():
        sys.exit(f"feature archive: no active work folder '{slug}'")
    if (src / BINDING_RECORD).is_file():
        sys.exit(f"feature archive: refused\n  {BINDING_RECORD} binds backlog items to this epic; "
                 f"the close flips them to done, a plain move would leave them scheduled · next: devkit epic close {slug}")
    problems = []
    readme = src / "README.md"
    if not readme.is_file():
        problems.append("README.md is missing (it must state the outcome)")
    elif STUB_MARK in readme.read_text(encoding="utf-8"):
        problems.append(f"README.md still carries the stub marker '{STUB_MARK}' — state the outcome and delete the line")
    t, e = load_yaml(src / "tracker.yaml")
    if e or not isinstance(t, dict):
        problems.append(f"tracker.yaml unreadable ({e or 'not a mapping'})")
    else:
        for p in phase_list(t):
            if p.get("status") not in CLOSED_PHASES:
                problems.append(f"phase {p['id']} is '{p.get('status')}', not one of {list(CLOSED_PHASES)}")
    if problems:
        sys.exit("feature archive: refused\n  " + "\n  ".join(problems))
    dest = root() / "docs/features/archive" / str(datetime.date.today().year) / slug
    if dest.exists():
        sys.exit(f"feature archive: {rel(dest)} already exists")
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dest))
    print(f"{rel(src)} -> {rel(dest)}")
    return 0


def ready_phases(t: dict) -> dict[int, list[dict]]:
    ph = phase_list(t)
    done = {p["id"] for p in ph if p.get("status") == "done"}
    waves: dict[int, list[dict]] = {}
    for p in ph:
        if p.get("status") not in SKIPPED and all(d in done for d in as_list(p.get("depends_on"))):
            waves.setdefault(p["wave"] if is_int(p.get("wave")) else 0, []).append(p)
    return waves


def cmd_tracker_next(slug: str | None) -> int:
    epics = [(s, e) for s, e in active_epics() if slug in (None, s)]
    if slug and not epics:
        print(f"no active epic '{slug}'", file=sys.stderr)
        return 1
    rc = 0
    for s, edir in epics:
        t, e = load_yaml(edir / "tracker.yaml")
        if e or not isinstance(t, dict):
            print(f"{s}: tracker unreadable ({e or 'not a mapping'})", file=sys.stderr)
            rc = 1
            continue
        waves = ready_phases(t)
        print(f"{s}:" + ("" if waves else " nothing ready"))
        for w in sorted(waves):
            print(f"  wave {w}")
            for p in waves[w]:
                area = ", ".join(str(a) for a in as_list(p.get("area")))
                print(f"    {p['id']}  {p.get('title', '')}  [{p.get('status')}]  area: {area}")
    return rc


def cmd_resume() -> int:
    """Hook entry point: never fails, never blocks."""
    try:
        for slug, edir in active_epics():
            try:
                t, e = load_yaml(edir / "tracker.yaml")
                if e or not isinstance(t, dict) or t.get("status") == "done":
                    continue
                r = t.get("resume") if isinstance(t.get("resume"), dict) else {}
                h = str(r.get("handoff", "none"))
                parts = [f"wave {r['current_wave']}"] if "current_wave" in r else []  # optional keys: a missing one is skipped
                if r.get("next"):
                    parts.append("next: " + " ".join(str(r["next"]).split()))
                print(f"{slug}: " + " · ".join(parts) if parts else slug)
                print(f"  handoff: {h if h == 'none' else rel(edir / h)}")
            except Exception:
                continue
    except Exception:
        pass
    return 0


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(prog="docs.py", description=__doc__.splitlines()[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    adr = sub.add_parser("adr").add_subparsers(dest="sub", required=True).add_parser("new")
    adr.add_argument("title", nargs="?")
    adr.add_argument("--scope")
    adr.add_argument("--status")
    bl = sub.add_parser("backlog").add_subparsers(dest="sub", required=True).add_parser("new")
    bl.add_argument("title", nargs="?")
    bl.add_argument("--epic")
    bl.add_argument("--priority")
    bl.add_argument("--origin")
    ft = sub.add_parser("feature").add_subparsers(dest="sub", required=True)
    ft.add_parser("new").add_argument("slug")
    ft.add_parser("archive").add_argument("slug")
    sub.add_parser("index")
    ck = sub.add_parser("check")
    ck.add_argument("--quiet", action="store_true")
    nx = sub.add_parser("tracker").add_subparsers(dest="sub", required=True).add_parser("next")
    nx.add_argument("slug", nargs="?")
    sub.add_parser("resume")
    a = ap.parse_args(argv)
    if a.cmd == "adr":
        return refuse("adr new is retired: ADR files are legacy and read-only", 'devkit rec ruling new "<summary>" --area <glob>')
    if a.cmd == "backlog":
        return refuse("backlog new is retired: backlog items are written by devkit rec", 'devkit rec backlog new "<title>"')
    if a.cmd == "feature":
        return cmd_feature_new(a.slug) if a.sub == "new" else cmd_feature_archive(a.slug)
    if a.cmd == "index":
        return cmd_index()
    if a.cmd == "check":
        return cmd_check(a.quiet)
    if a.cmd == "tracker":
        return cmd_tracker_next(a.slug)
    return cmd_resume()


if __name__ == "__main__":
    sys.exit(main())
